// Extracts every literal RCON command the panel sends anywhere in apps/panel-server/
// and compares it against the command list reported by the live server
// (rcon "help", one command per line, path given as the 2nd argument).
//
// Usage: node scripts/audit-rcon-commands.mjs <repo-root> <supported-commands-file>
// <supported-commands-file> is NOT generated by this repo -- it must come
// from a real running Project Zomboid server's own `help` RCON response,
// captured by hand or by a separate script outside this one. This tool has
// zero references anywhere in this repo (package.json, CI workflows, docs)
// as of this fix -- there was no documented way to actually run it before
// this comment existed. If you don't have one, run with just the repo root
// to see the panel-side denominator alone (see the argv.length branch
// below) -- that half needs no live server at all.
//
// Scan every server-side JavaScript file instead of maintaining a list of
// call sites. This keeps new RCON dispatches in the audit automatically.
import fs from "fs";
import path from "path";

const root = path.resolve(process.argv[2] || ".");
const supportedFile = process.argv[3];

const SKIP_DIRS = new Set(["tests", "node_modules", "__fixtures__", "data", "database"]);

function collectJsFiles(dir, out) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      if (SKIP_DIRS.has(entry.name)) continue;
      collectJsFiles(path.join(dir, entry.name), out);
    } else if (entry.isFile() && entry.name.endsWith(".js")) {
      out.push(path.join(dir, entry.name));
    }
  }
  return out;
}

const serverDir = path.join(root, "apps/panel-server");
const files = collectJsFiles(serverDir, []);

// A single pattern, not three: `execute\w*\(` with no receiver anchor
// already matches `this.execute(`, `this.client.execute(`, and
// `rconService.execute(` as substrings regardless of what precedes them --
// the three separate patterns this file used to carry were two exact
// duplicates of the third wearing different names, the same "pattern that
// can only ever match what another pattern already matches" shape as the
// dead `executeAction(` pattern just removed from audit-bridge-routes.mjs.
const pattern = /execute\w*\(\s*[`"']([a-zA-Z]+)/g;

const found = new Map();
for (const file of files) {
  const text = fs.readFileSync(file, "utf8");
  for (const m of text.matchAll(pattern)) {
    const rel = path.relative(root, file).replace(/\\/g, "/");
    if (!found.has(m[1])) found.set(m[1], rel);
  }
}

// Also catch commands assigned to a local variable before execute() receives
// the variable. The direct-literal pattern cannot see that call shape.
// find `word` = a template/string literal starting with a lowercase command
// word, then check that SAME variable name is later passed to execute() in
// the same file.
const varPattern = /(?:let|const)\s+(\w+)\s*=\s*[`"']([a-zA-Z]+)/g;
for (const file of files) {
  const text = fs.readFileSync(file, "utf8");
  for (const m of text.matchAll(varPattern)) {
    const [, varName, word] = m;
    if (found.has(word)) continue;
    if (new RegExp(`execute\\w*\\(\\s*${varName}\\b`).test(text)) {
      const rel = path.relative(root, file).replace(/\\/g, "/");
      found.set(word, rel);
    }
  }
}

// Same "fail loudly rather than silently narrow" rule the sibling scripts
// were just fixed to follow: an implausibly small count here means the
// pattern or the directory walk broke, not that the panel genuinely only
// sends a handful of commands.
const MIN_COMMANDS = 20;
if (found.size < MIN_COMMANDS) {
  console.error(
    `ERROR: found only ${found.size} distinct command(s) across apps/panel-server/ ` +
    `(expected at least ${MIN_COMMANDS}). The extraction pattern or the file walk is ` +
    `almost certainly broken -- fix it before trusting this script's output.`,
  );
  process.exit(1);
}

console.log(`panel sends ${found.size} distinct commands (across ${files.length} files scanned under apps/panel-server/)`);

if (!supportedFile) {
  console.log(
    "\nNo supported-commands file given -- printing the panel-side denominator only. " +
    "Pass a real server's `help` RCON output (one command per line) as the 2nd argument " +
    "to check these against what the server actually supports:",
  );
  for (const [command, file] of [...found.entries()].sort()) {
    console.log(`  ${command} (${file})`);
  }
  process.exit(0);
}

const supported = new Set(
  fs
    .readFileSync(supportedFile, "utf8")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean),
);

const unsupported = [...found.keys()].filter((c) => !supported.has(c)).sort();
const ok = [...found.keys()].filter((c) => supported.has(c)).sort();

console.log(`server reports ${supported.size} commands`);
console.log(`VERIFIED: ${ok.join(", ")}`);
console.log(`NOT IN SERVER COMMAND LIST: ${unsupported.length ? unsupported.map((c) => `${c} (${found.get(c)})`).join(", ") : "none"}`);
